Method.Implementation:
$$$TRACE("InTouchWorksEventJdbc: Read Event_Table - OnProcessInput, process: " _ pInput.RowCount) set tSC = "" set req = ##class(IHC.ITF.ITFCOMMON.DataStructure.EventSequence).%New() for j=1:1:pInput.ColCount { $$$TRACE("Col Nm: " _ pInput.GetColumnName(j)) }
if (pInput.RowCount > 0) { set req.EventSequenceID=pInput.Get("EventSequenceID") set req.CreatedDTTM=pInput.Get("CreatedDTTM") set req.EventCode=pInput.Get("EventCode") set req.Status=pInput.Get("Status") set req.PersonID=pInput.Get("PersonID") set req.ActivityID=pInput.Get("ActivityID") set req.ItemID=pInput.Get("ItemID") set req.VisitID=pInput.Get("VisitID") set req.EncounterID=pInput.Get("EncounterID") set req.OrderID=pInput.Get("OrderID") set req.ChargeID=pInput.Get("ChargeID") set req.QueryID=pInput.Get("QueryID") set req.ReferralNumber=pInput.Get("ReferralNumber") set req.SubItemNumber=pInput.Get("SubItemNumber") set req.ResponseFLAG=pInput.Get("ResponseFLAG")
$$$TRACE("EventSequenceID: " _ req.EventSequenceID)
For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W") Continue:""=tOneTarget $$$TRACE("Sending input "_req _ "' to '"_tOneTarget_"'")
Set tSC1=..SendRequestSync(tOneTarget,req) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
}
}
Quit tSC
